<?php require __DIR__.'/includes/bootstrap.php';require_permission('settings.manage');require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['company_name','currency','timezone','date_format','session_timeout','low_stock_enabled'] as $k){$v=trim((string)($_POST[$k]??''));$pdo->prepare('INSERT INTO system_settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)')->execute([$k,$v,user()['id']]);}audit($pdo,'update','settings');flash('success','System settings updated.');redirect('settings.php');}$settings=array_column($pdo->query('SELECT setting_value,setting_key FROM system_settings')->fetchAll(),'setting_value','setting_key');render_header('Settings','settings');page_title('System Settings','APPLICATION CONFIGURATION','Manage business identity, localization and operating rules.');?><article class="card form-card"><form method="post"><?=csrf_field()?><div class="form-grid"><label>Company Name<input name="company_name" value="<?=e($settings['company_name']??'HESH & FRN Operations')?>"></label><label>Currency<input name="currency" value="<?=e($settings['currency']??'QAR')?>"></label><label>Timezone<select name="timezone"><option>Asia/Qatar</option><option>UTC</option></select></label><label>Date Format<select name="date_format"><option value="d M Y">07 Oct 2026</option><option value="d/m/Y">07/10/2026</option><option value="Y-m-d">2026-10-07</option></select></label><label>Session Timeout (seconds)<input type="number" name="session_timeout" value="<?=e($settings['session_timeout']??'7200')?>"></label><label>Low Stock Alerts<select name="low_stock_enabled"><option value="1">Enabled</option><option value="0">Disabled</option></select></label></div><div class="form-actions"><button class="btn primary">Save Settings</button></div></form></article><?php render_footer('settings');
